"""Bilingual ten-page report and two-page executive brief; formulas only.
Financial content selects active/reference outputs from the same V06 core.
"""
from core import *
import os
SECTIONS=[('Síntese Executiva de Investimento','Executive Investment Summary'),('Orçamento de Desenvolvimento e Financiamento','Development Budget & Funding'),('Tesouraria e Sustentabilidade da Dívida','Cash Flow & Debt Sustainability'),('Promoção Imobiliária e Vendas','Real Estate Development & Sales'),('Retornos dos Proprietários Residenciais','Residential Owner Returns'),('Exploração Hoteleira e Centro MICE','Hotel & MICE Operations'),('Fiscalidade, Operadoras e Reservas','Taxation, Operator Terms & Reserves'),('Estrutura Acionista e Retornos','Shareholding & Equity Returns'),('Sensibilidades, Riscos e Equilíbrio','Sensitivities, Risks & Break-even'),('Avaliação do Investimento e Decisões','Investment Assessment & Key Decisions')]
def build(st):
 wb=st['wb'];model=st['model'];fm=st['fm2'];fields=st['fields'];p=st['effective'];lang=st['lang'];tr=st['tr'];main=st['main'];ref=st['reference_model'];active=st['metrics']['Base'];baseline=st['metrics']['Reference Case'];rc=fields['report_case'].eq('Reference Case')
 def choose(a,b):return IF(rc,b,a)
 def metric(k):return choose(active[k],baseline[k])
 def total(k):return choose(rng([r[k] for r in main['rows']]),rng([r[k] for r in ref['rows']]))
 def month(k,m):return choose(main['rows'][m-1][k],ref['rows'][m-1][k])
 def param(k):return choose(p[k],ref['params'][k])
 # Presentation styles use numeric currency formats; no financial TEXT() cells.
 styles={}
 for key,extra in {'brand':{'font_size':13,'font_color':'FFFFFF','bold':True,'bg_color':'B31F2B'},'title':{'font_size':16,'bold':True,'text_wrap':True,'valign':'vcenter'},'sub':{'font_size':8,'font_color':'526A80','text_wrap':True},'section':{'font_size':15,'bold':True,'font_color':'B31F2B','text_wrap':True},'label':{'font_size':9,'font_color':'43576B','bg_color':'F2F5F8','text_wrap':True,'valign':'vcenter'},'money':{'font_size':17,'bold':True,'bg_color':'F2F5F8','num_format':'#,##0 "€";[Red](#,##0) "€";–'},'number':{'font_size':17,'bold':True,'bg_color':'F2F5F8','num_format':'#,##0'},'pct':{'font_size':17,'bold':True,'bg_color':'F2F5F8','num_format':'0.00%'},'ratio':{'font_size':17,'bold':True,'bg_color':'F2F5F8','num_format':'0.00"×"'},'text':{'font_size':9,'text_wrap':True,'valign':'vcenter'},'head':{'font_size':9,'bold':True,'bg_color':'344C62','font_color':'FFFFFF','text_wrap':True},'num':{'font_size':9,'num_format':'#,##0.00;[Red](#,##0.00)'},'percent':{'font_size':9,'num_format':'0.00%'},'note':{'font_size':9,'bg_color':'F2F5F8','text_wrap':True,'valign':'vcenter'},'alert':{'font_size':10,'bold':True,'font_color':'B31F2B','text_wrap':True,'valign':'vcenter'}}.items():styles[key]=wb.add_format({'font_name':'Aptos','font_color':'203246',**extra})
 bindings=[]
 def make_sheet(name,pages):
  s=wb.add_worksheet(name);s.hide_gridlines(2);s.hide_row_col_headers();s.freeze_panes(6,0);s.set_zoom(100);s.set_column('A:L',7);s.set_default_row(14);s.set_portrait();s.set_paper(9);s.set_print_scale(100);s.set_margins(.3,.3,.3,.3);s.print_area(0,0,pages*50-1,11);s.set_h_pagebreaks([50*i for i in range(1,pages)]);s.set_footer('&LKK-01 · EFCC · Native Excel acceptance pending&R&P / &N');return s
 report=make_sheet('DASH 10 V06',10);brief=make_sheet('V06 Brief',2)
 def merged(s,r,c1,c2,x,fmt='text',height=1):
  x=asx(x);s.merge_range(r,c1,r+height-1,c2,'',styles[fmt]);s.write_formula(r,c1,'='+x.f,styles[fmt],x.v)
  if not isinstance(x.v,str):bindings.append({'sheet':s.name,'cell':col(c1)+str(r+1),'formula':x.f,'value':x.v})
 def txt(s,o,r,pt,en,fmt='text',height=2):
  f=tr(f'EFCC.report.{s.name}.{o+r}',pt,en);merged(s,o+r,0,11,X(f,pt),fmt,height)
 def start(s,i,section):
  o=(i-1)*50;s.merge_range(o,0,o+1,8,'KK-01 | HOTEL & RESIDENCES',styles['brand']);s.merge_range(o,9,o+1,11,'',wb.add_format({'bg_color':'FFFFFF'}))
  logo=Path(os.environ.get('KK01_LOGO','/workspace/shared/logo jscv(1).jpg'))
  if logo.exists():
   from PIL import Image
   with Image.open(logo) as im:w,h=im.size
   scale=min(150/w,34/h);s.insert_image(o,9,str(logo),{'x_scale':scale,'y_scale':scale,'x_offset':2,'y_offset':2})
  title=tr('EFCC.report.title','10 — Relatório Executivo Consolidado de Viabilidade e Investimento','10 — Consolidated Investment & Feasibility Report');merged(s,o+3,0,11,X(title,'10 — Relatório Executivo Consolidado de Viabilidade e Investimento'),'title',3)
  f=tr('EFCC.report.section.'+str(section),f'{section:02} — '+SECTIONS[section-1][0],f'{section:02} — '+SECTIONS[section-1][1]);merged(s,o+7,0,11,X(f,f'{section:02} — '+SECTIONS[section-1][0]),'section',2)
  s.merge_range(o+2,0,o+2,3,'',styles['sub']);s.write_formula(o+2,0,'=HYPERLINK("#\'V06 Controlos\'!B5",'+lang+'&" ▾")',styles['sub'],'PT ▾')
  s.merge_range(o+2,4,o+2,11,'',styles['sub']);s.write_formula(o+2,4,'=HYPERLINK("#\'V06 Hipoteses\'!D26",'+fields['report_case'].f+'&" · "&'+fields['scenario_id'].f+'&" · "&'+fields['report_date'].f+')',styles['sub'],fields['report_case'].v+' · '+fields['scenario_id'].v+' · '+fields['report_date'].v)
  s.merge_range(o+10,0,o+10,3,'',styles['sub']);s.write_url(o+10,0,"internal:'EXEC V06'!A1",styles['sub'],string='← Executive')
  s.merge_range(o+10,4,o+10,7,'',styles['sub']);target='V06 Brief' if fields['report_mode'].v=='Executive Brief' else 'DASH 10 V06';s.write_formula(o+10,4,'=HYPERLINK(IF('+fields['report_mode'].f+'="Executive Brief","#\'V06 Brief\'!A1","#\'DASH 10 V06\'!A1"),'+fields['report_mode'].f+')',styles['sub'],fields['report_mode'].v)
  s.merge_range(o+10,9,o+10,11,'',styles['sub']);s.write_url(o+10,9,"internal:'V06 Imprimir'!A1",styles['sub'],string='Print / PDF')
  txt(s,o,46,'Fonte: motor V06 · valores de estudo · EUR · 180 meses · parâmetros registados.','Source: V06 engine · study values · EUR · 180 months · recorded parameters.','sub',1)
  txt(s,o,48,'Candidato · recálculo independente realizado; aceitação Microsoft Excel 365 pendente.','Candidate · independent recalculation performed; Microsoft Excel 365 acceptance pending.','sub',1)
  return o
 def cards(s,o,items):
  for i,(pt,en,x,fmt) in enumerate(items):
   r=o+13+(i//2)*5;c=(i%2)*6;f=tr(f'EFCC.report.card.{s.name}.{r}.{c}',pt,en);merged(s,r,c,c+5,X(f,pt),'label',2);merged(s,r+2,c,c+5,x,fmt,2)
 def table(s,o,row,records):
  for i,(pt,en,x,fmt) in enumerate(records):
   r=o+row+i*2;f=tr(f'EFCC.report.table.{s.name}.{r}',pt,en);merged(s,r,0,7,X(f,pt),'text',2);merged(s,r,8,11,x,fmt,2)
 o=start(report,1,1);cards(report,o,[('CAPEX futuro','Future CAPEX',total('capex'),'money'),('VGV — 94 frações','Sales value — 94 apartments',choose(X("SUM('V06 Unidades'!H5:H98)",sum(u['price'].v for u in model.units)),asx(sum(u['price'].v for u in model.units))),'money'),('TIR novos investidores','New investor IRR',metric('irr'),'pct'),('MOIC novos investidores','New investor MOIC',metric('moic'),'ratio'),('VAL novos investidores','New investor NPV',metric('npv'),'money'),('Equity Value saída','Exit Equity Value',metric('exit'),'money')]);txt(report,o,30,'Hotel 200 quartos · 94 frações · MICE. Projeto em Kebra Kanela, Praia, Cabo Verde.','200-room hotel · 94 apartments · MICE. Kebra Kanela, Praia, Cabo Verde.','note',3)
 alert=IF(metric('gap')>.01,IF(X(lang,'PT').eq('PT'),'Défice de financiamento: retornos condicionais.','Funding gap: returns conditional.'),IF(metric('npv')<0,IF(X(lang,'PT').eq('PT'),'VAL negativo à taxa exigida; rever condições e risco.','Negative NPV at required return; review terms and risk.'),IF(X(lang,'PT').eq('PT'),'VAL não negativo no cenário de estudo; validar contratos.','Non-negative NPV in study case; validate contracts.')));merged(report,o+35,0,11,alert,'alert',3);table(report,o,40,[('Desconto equity','Equity discount',param('discount'),'percent'),('Cenário Hotel de referência','Reference hotel case',choose(fields['hotel_mode'],asx('Base Case')),'text')])
 o=start(report,2,2);cards(report,o,[('Investimento histórico — sem saída futura','Historical investment — no future outflow',asx(4500000),'money'),('CAPEX futuro','Future CAPEX',total('capex'),'money'),('Capital KK cenário','Scenario KK capital',total('equity'),'money'),('Pico de dívida','Peak debt',metric('debt'),'money')]);table(report,o,25,[('Construção e equipamento inicial','Construction and initial FF&E',total('construction'),'num'),('Fiscalização','Supervision',total('supervision'),'num'),('Contingência utilizada','Contingency paid',total('contingency_paid'),'num'),('ETC adicional','Additional ETC',total('extra_etc'),'num'),('Desembolsos banco acumulados','Cumulative bank draws',total('draw'),'num')]);txt(report,o,38,'25 M€ / oito tickets: cenário de subscrição; capital efetivamente recebido exige prova documental. Linha não renovável: reutilização não presumida.','EUR 25m / eight tickets: subscription scenario; actual capital receipts require documentary evidence. Non-revolving facility: reuse is not presumed.','note',5)
 o=start(report,3,3);cards(report,o,[('Caixa M30','Cash M30',metric('cash30'),'money'),('Caixa M42','Cash M42',metric('cash42'),'money'),('Caixa M54','Cash M54',metric('cash54'),'money'),('Juros totais','Total interest',metric('interest'),'money'),('Défice máximo','Maximum funding gap',metric('gap'),'money'),('Insuficiência reserva','Reserve shortfall',metric('reservegap'),'money')]);table(report,o,30,[('Reserva geral ativa','Active general reserve',param('reserve'),'num'),('Carência principal — meses','Principal grace — months',param('grace'),'num'),('Prazo pós-carência — meses','Post-grace tenor — months',param('term'),'num'),('Cobertura histórica exigida','Required prior coverage',param('coverage'),'num'),('Dívida M180','M180 debt',month('debt',180),'num')]);txt(report,o,42,'DSCR Hotel exclui IRPC consolidado; não representa covenant bancário aprovado. Ver V06 Anual para série e bases.','Hotel DSCR excludes consolidated corporate tax; it is not an approved bank covenant. See V06 Anual for series and bases.','note',3)
 o=start(report,4,4);cards(report,o,[('Frações','Apartments',asx(94),'number'),('Recebimentos previstos 180M','Forecast collections 180M',total('receipts'),'money'),('Custos comerciais','Selling costs',total('sales_cost'),'money'),('Margem promoção — proxy','Development margin — proxy',total('sales_profit'),'money')]);table(report,o,25,[('Sinal de estudo','Study deposit',asx(.05),'percent'),('Primeira tranche','First tranche',asx(.20),'percent'),('Prestações semestrais','Semiannual instalments',asx(.55),'percent'),('Escritura — remanescente','Deed — remainder',asx(.20),'percent'),('Diferença reconciliação mensal','Monthly reconciliation difference',X("MAX('V06 Conciliacao Vendas'!D5:D184)",0),'num')]);# reconciliation derived from schedule checks

 txt(report,o,38,'Inventário único: V06 Unidades. Disponibilidade e calendário: V06 Disponibilidade / Calend 01. Sold/Reserved/Available/Deeded documentais separados da previsão; valores em falta são “Not documented”.','Single inventory: V06 Unidades. Availability and schedules: V06 Disponibilidade / Calend 01. Documented Sold/Reserved/Available/Deeded remain separate from forecast; missing values are “Not documented”.','note',5)
 o=start(report,5,5);cards(report,o,[('Receita residencial','Residential revenue',total('res_revenue'),'money'),('Rendas suportáveis','Affordable owner distributions',total('owner_distribution'),'money'),('Yield alvo não coberto','Uncovered target yield',total('owner_shortfall'),'money'),('Residual KK','KK residual',total('res_kk'),'money')]);table(report,o,25,[('Fees gestão residencial','Residential management fees',total('res_management_fee'),'num'),('Fees agregados residencial','Residential aggregate fees',total('res_distribution_fee'),'num'),('FF&E residencial','Residential FF&E',total('res_ffe'),'num'),('Fundo adicional pool','Additional pool fund',total('res_fund'),'num'),('Yield inicial objetivo','Initial target yield',param('res_yield'),'percent')]);txt(report,o,38,'A renda é limitada à caixa do pool e separada do Hotel. Yield alvo não é garantia. Imposto dos proprietários não confirmado; a análise não representa retorno líquido fiscal individual.','Owner payments are limited to pool cash and separate from Hotel. Target yield is not guaranteed. Owner tax is unconfirmed; analysis is not an individual after-tax return.','note',5)
 o=start(report,6,6);opening=31+int(p['construction_delay'].v);cards(report,o,[('ADR abertura','Opening ADR',month('adr',opening),'money'),('Ocupação abertura','Opening occupancy',month('occupancy',opening),'pct'),('Receita Hotel + MICE 180M','Hotel + MICE revenue 180M',total('revenue'),'money'),('EBITDA Ano15','Year15 EBITDA',metric('ebitda15'),'money')]);table(report,o,25,[('Receita quartos','Room revenue',total('room_revenue'),'num'),('F&B Hotel — exclui banquetes MICE','Hotel F&B — excludes MICE banquets',total('fb_revenue'),'num'),('Receita MICE','MICE revenue',total('mice_revenue'),'num'),('GOP','GOP',total('gop'),'num'),('Fees operadora','Operator fees',total('operator_fees'),'num'),('FF&E dotação / fundo final','FF&E contribution / closing fund',total('ffe'),'num')]);txt(report,o,40,'MICE: índice sobre modelo original; faltam dias disponíveis, eventos, participantes e preços por evento documentados. FF&E é dotação restrita; a utilização prevista não comprova gasto efetivo.','MICE: index on original model; documented event days, volume, attendance and event pricing are missing. FF&E is restricted allocation; forecast use is not actual expenditure evidence.','note',4)
 o=start(report,7,7);cards(report,o,[('IRPC pago','Corporate tax paid',metric('tax'),'money'),('Pico crédito IVA','Peak VAT credit',metric('vatcredit'),'money'),('Seguros totais','Total insurance',metric('insurance'),'money'),('Reserva HOTUSA','HOTUSA reserve',param('hotusa'),'money')]);table(report,o,25,[('Fee base Hotel / receita','Hotel base fee / revenue',param('base_fee'),'percent'),('Agregado M+D+S Hotel / receita','Hotel aggregate M+D+S / revenue',param('systems'),'percent'),('Incentivo / GOP após fees','Incentive / GOP after fees',param('incentive'),'percent'),('Fundo FF&E final — excluído da saída','Closing FF&E fund — excluded from exit',month('ffe_restricted_fund',180),'num'),('Impostos a pagar M180','Tax payable M180',month('tax_payable',180),'num')]);txt(report,o,38,'Incentivos são cenários, não benefícios concedidos. Perfis de operadoras são estudo negocial, não propostas contratuais comprovadas. HOTUSA é reserva jurídica, não dívida reconhecida.','Incentives are scenarios, not granted benefits. Operator profiles are negotiation studies, not evidenced contractual proposals. HOTUSA is a legal contingency reserve, not recognised debt.','note',5)
 o=start(report,8,8);cards(report,o,[('Dividendos M54','M54 dividends',metric('div54'),'money'),('Dividendos até saída','Dividends through exit',metric('dividends'),'money'),('TIR novos investidores','New investor IRR',metric('irr'),'pct'),('MOIC novos investidores','New investor MOIC',metric('moic'),'ratio')]);table(report,o,25,[('JSCV','JSCV',asx(.4),'percent'),('JALS','JALS',asx(.1),'percent'),('Novos investidores','New investors',asx(.5),'percent'),('VAL novos investidores','New investor NPV',metric('npv'),'num'),('Equity Value saída','Exit Equity Value',metric('exit'),'num')]);txt(report,o,38,'15 blocos / oito tickets novos. Dividendos desde M54 sujeitos a dívida liquidada, reservas, lucros e cobertura dos 12 meses anteriores ≥1,20×. Custos e datas históricos dos promotores insuficientes para TIR individual.','15 blocks / eight new tickets. Dividends from M54 require debt repayment, reserves, profits and prior-12-month coverage ≥1.20×. Historical promoter costs and dates are insufficient for individual IRR.','note',5)
 o=start(report,9,9);cards(report,o,[('VAL ativo','Active NPV',active['npv'],'money'),('VAL referência','Reference NPV',baseline['npv'],'money'),('Taxa retorno exigida','Required return',p['discount'],'pct'),('Pico dívida ativo','Active peak debt',active['debt'],'money')]);table(report,o,25,[('ADR para VAL ≥ 0 à ocupação selecionada','ADR for NPV ≥ 0 at selected occupancy',X("'V06 Equilibrio'!B5",'See tested grid'),'text'),('Ocupação para VAL ≥ 0 ao ADR selecionado','Occupancy for NPV ≥ 0 at selected ADR',X("'V06 Equilibrio'!B6",'See tested grid'),'text'),('EBITDA mínimo nos casos viáveis testados','Minimum EBITDA among feasible tested cases',X("'V06 Equilibrio'!B7",'See tested grid'),'text')]);txt(report,o,34,'Matriz: 30 casos ADR 150–250 € / ocupação 50–75%, pelo mesmo motor 180M. O equilíbrio é discreto, condicionado à grelha, sem extrapolação. Comparativos ativos não são sensibilidades congeladas da referência.','Matrix: 30 ADR EUR 150–250 / occupancy 50–75% cases, same 180M engine. Break-even is discrete, grid-constrained, without extrapolation. Active comparisons are not frozen-reference sensitivities.','note',5);txt(report,o,40,'Riscos: capital e vendas não documentados, IVA/IRPC e incentivos, sobrecustos, capacidade MICE, contratos de gestão, financiamento e múltiplo de saída.','Risks: undocumented capital and sales, VAT/corporate tax and incentives, overruns, MICE capacity, management contracts, funding and exit multiple.','alert',4)
 o=start(report,10,10);table(report,o,13,[('Promotor: valor de saída a validar','Promoter: exit value requires validation',metric('exit'),'num'),('Investidores: VAL à taxa exigida','Investors: NPV at required return',metric('npv'),'num'),('Banco: défice máximo não coberto','Bank: maximum unfunded gap',metric('gap'),'num'),('Compradores: objetivo de renda não coberto','Buyers: uncovered owner target',total('owner_shortfall'),'num'),('Operadora Hotel: fees totais previstos','Hotel operator: forecast total fees',total('operator_fees'),'num')]);txt(report,o,25,'Promotor: rentabilidade histórica indisponível sem custos e datas. Investidores: comparar TIR com desconto ativo e VAL com zero. Banco: DSCR 1,30× é apenas referência interna, não covenant aprovado.','Promoter: historical return unavailable without costs and dates. Investors: compare IRR with active discount and NPV with zero. Bank: 1.30× DSCR is an internal reference, not an approved covenant.','note',6);txt(report,o,32,'Compradores: confirmar preço, contrato, despesas e tributação; yield não garantido. Operadora: faltam contrato, orçamento de execução e limiar de retorno próprio para concluir atratividade.','Buyers: confirm price, contract, costs and tax; yield is not guaranteed. Operator: contract, execution budget and its own required-return threshold are missing for an attractiveness conclusion.','note',5);txt(report,o,38,'Decisões: formalizar capital, vendas e dívida; validar fiscalidade e reservas; negociar fees; comprovar mercado e MICE; testar nativamente no Excel antes de aprovação institucional.','Decisions: formalise capital, sales and debt; validate tax and reserves; negotiate fees; evidence market and MICE assumptions; test natively in Excel before institutional approval.','alert',5)
 for i in [1,2]:
  o=start(brief,i,1 if i==1 else 10)
  if i==1:
   cards(brief,o,[('CAPEX futuro','Future CAPEX',total('capex'),'money'),('Capital KK cenário','Scenario KK capital',total('equity'),'money'),('TIR investidores','Investor IRR',metric('irr'),'pct'),('VAL investidores','Investor NPV',metric('npv'),'money'),('MOIC investidores','Investor MOIC',metric('moic'),'ratio'),('Equity Value saída','Exit Equity Value',metric('exit'),'money')]);merged(brief,o+31,0,11,alert,'alert',3);table(brief,o,37,[('Desconto equity','Equity discount',param('discount'),'percent'),('Pico dívida','Peak debt',metric('debt'),'num'),('Défice máximo','Maximum funding gap',metric('gap'),'num')])
  else:
   table(brief,o,13,[('Dividendos M54','M54 dividends',metric('div54'),'num'),('EBITDA Ano15','Year15 EBITDA',metric('ebitda15'),'num'),('Reserva geral','General reserve',param('reserve'),'num'),('Reserva HOTUSA','HOTUSA reserve',param('hotusa'),'num'),('IRPC pago','Corporate tax paid',metric('tax'),'num')]);txt(brief,o,25,'Condições: contratos e capital documentados; fiscalidade e incentivos validados; dívida e reservas asseguradas. Dividendos e saída são simulações. Yield dos proprietários não garantido.','Conditions: documented contracts and capital; validated tax and incentives; secured debt and reserves. Dividends and exit are simulations. Owner yield is not guaranteed.','note',6);txt(brief,o,33,'Análise separada: promotor sem TIR histórica documentada; investidores avaliados por VAL/TIR; banco sujeito a covenants; compradores sujeitos a contrato e impostos; operadora sem limiar de retorno próprio comprovado.','Separate assessments: promoter lacks documented historical IRR; investors assessed using NPV/IRR; bank subject to covenants; buyers subject to contracts and tax; operator has no evidenced own-return threshold.','note',7)
 st['report_bindings']=bindings
